1	package githelper
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"errors"
8		"fmt"
9		"io"
10		"os"
11		"os/exec"
12		"strings"
13	
14		"github.com/entireio/cli/internal/remotehelper/debuglog"
15		"github.com/entireio/cli/internal/remotehelper/gitproto"
16	)
17	
18	// handlePush implements the git-remote-helpers "push" / "push for-push"
19	// command sequence. Git sends a batch of "push <src>:<dst>" lines
20	// terminated by a blank line; we shell out to
21	//
22	//	git send-pack --stateless-rpc --helper-status --stdin <url>
23	//
24	// to do all the heavy lifting (computing reachable objects, building
25	// the pack, parsing the v0 ref advertisement, framing the
26	// receive-pack request, parsing report-status). Send-pack's
27	// stdin/stdout are the "connection" in stateless-rpc mode, so we
28	// bridge that to a single HTTP POST against /git-receive-pack — this
29	// preserves our scoped-token auth and replica-failover path.
30	//
31	// Protocol flow (mirroring remote-curl.c:push_git + rpc_service):
32	//  1. Read remaining "push <src>:<dst>" lines from git until blank
33	//     line.
34	//  2. Fetch v0 info/refs?service=git-receive-pack (the ref
35	//     advertisement send-pack would normally read from the network).
36	//  3. Feed refspecs (as pktlines + flush) + advertisement to
37	//     send-pack stdin.
38	//  4. Read send-pack stdout as a receive-pack request body (refs +
39	//     capabilities + flush, then PACK data for non-delete updates).
40	//  5. POST it to /git-receive-pack, stream response back into
41	//     send-pack stdin.
42	//  6. Send-pack writes a trailing flush + helper-status lines to
43	//     stdout; we discard the flush and relay helper-status to git,
44	//     then append the blank line that terminates the status batch.
45	func handlePush(ctx context.Context, t Transport, firstLine string, opts *Options, stdin *bufio.Reader, stdout io.Writer) error {
46		refspecs, err := readPushBatch(firstLine, stdin)
47		if err != nil {
48			return err
49		}
50	
51		refsResp, err := t.InfoRefs(ctx, serviceReceivePack)
52		if err != nil {
53			return fmt.Errorf("fetching receive-pack info/refs: %w", err)
54		}
55		advertisement, err := gitproto.ReadPostServiceAdvertisement(refsResp)
56		_ = refsResp.Close()
57		if err != nil {
58			return fmt.Errorf("reading receive-pack info/refs: %w", err)
59		}
60	
61		var preamble bytes.Buffer
62		for _, spec := range refspecs {
63			fmt.Fprintf(&preamble, "%04x%s\n", len(spec)+5, spec)
64		}
65		preamble.WriteString("0000")
66	
67		args := append([]string{"send-pack", "--stateless-rpc", "--helper-status", "--stdin"},
68			opts.SendPackArgs()...)
69		args = append(args, t.ErrorBaseURL())
70		sp := exec.CommandContext(ctx, "git", args...)
71		sp.Stderr = os.Stderr
72		spIn, err := sp.StdinPipe()
73		if err != nil {
74			return fmt.Errorf("send-pack stdin pipe: %w", err)
75		}
76		spOut, err := sp.StdoutPipe()
77		if err != nil {
78			return fmt.Errorf("send-pack stdout pipe: %w", err)
79		}
80		if err := sp.Start(); err != nil {
81			return fmt.Errorf("starting send-pack: %w", err)
82		}
83	
84		respCh := make(chan io.Reader, 1)
85		feedErr := make(chan error, 1)
86		go func() {
87			defer spIn.Close()
88			if _, err := spIn.Write(preamble.Bytes()); err != nil {
89				feedErr <- fmt.Errorf("writing refspecs to send-pack: %w", err)
90				return
91			}
92			if _, err := spIn.Write(advertisement); err != nil {
93				feedErr <- fmt.Errorf("writing advertisement to send-pack: %w", err)
94				return
95			}
96			resp, ok := <-respCh
97			if !ok {
98				feedErr <- nil
99				return
100			}
101			if _, err := io.Copy(spIn, resp); err != nil {
102				feedErr <- fmt.Errorf("piping receive-pack response to send-pack: %w", err)
103				return
104			}
105			feedErr <- nil
106		}()
107	
108		spOutReader := bufio.NewReader(spOut)
109		var requestBody bytes.Buffer
110		if err := gitproto.ReadSendPackRequest(spOutReader, &requestBody); err != nil {
111			close(respCh)
112			killAndWaitSendPack(sp, "after reading send-pack request failed")
113			return fmt.Errorf("reading send-pack request: %w", err)
114		}
115		amendedBody, err := gitproto.AppendAgentToReceivePackRequest(requestBody.Bytes(), Agent)
116		if err != nil {
117			close(respCh)
118			killAndWaitSendPack(sp, "after amending receive-pack agent failed")
119			return fmt.Errorf("amending receive-pack agent: %w", err)
120		}
121	
122		resp, err := t.ServiceRPC(ctx, serviceReceivePack, bytes.NewReader(amendedBody))
123		if err != nil {
124			close(respCh)
125			killAndWaitSendPack(sp, "after posting receive-pack failed")
126			return fmt.Errorf("posting receive-pack: %w", err)
127		}
128		respCh <- resp
129		close(respCh)
130	
131		// Send-pack's stdout sequence after we write the response:
132		//   <0000>                       <- packet_flush(out) at send-pack.c:759
133		//   ok refs/heads/...            <- print_helper_status (plain text)
134		//   error refs/...
135		// Drain the trailing flush so git sees only the newline-delimited
136		// status lines that transport-helper.c:push_update_refs_status
137		// expects.
138		flushBuf := make([]byte, 4)
139		if _, err := io.ReadFull(spOutReader, flushBuf); err != nil {
140			_ = resp.Close()
141			return fmt.Errorf("reading send-pack trailing flush: %w", err)
142		}
143		if string(flushBuf) != "0000" {
144			_ = resp.Close()
145			return fmt.Errorf("expected trailing flush from send-pack, got %q", flushBuf)
146		}
147	
148		helperStatus, err := io.ReadAll(spOutReader)
149		_ = resp.Close()
150		if err != nil {
151			return fmt.Errorf("reading helper-status: %w", err)
152		}
153	
154		// Relay helper-status before checking exit codes. send-pack exits
155		// non-zero on per-ref rejections (D/F conflict, protected branch,
156		// hook decline); the buffered `error refs/X <reason>` lines are
157		// what git's transport-helper.c reads to print `! [remote rejected]
158		// refs/X (<reason>)`. Returning early on Wait/feed errors swallowed
159		// them, leaving users with only `send-pack exited with error: exit
160		// status 1`.
161		if _, err := stdout.Write(helperStatus); err != nil {
162			return fmt.Errorf("writing helper-status: %w", err)
163		}
164		if _, err := fmt.Fprintln(stdout); err != nil {
165			return fmt.Errorf("writing push terminator: %w", err)
166		}
167	
168		if err := <-feedErr; err != nil {
169			if waitErr := sp.Wait(); waitErr != nil {
170				return errors.Join(err, fmt.Errorf("send-pack exited after feeder error: %w", waitErr))
171			}
172			return err
173		}
174		if err := sp.Wait(); err != nil {
175			return fmt.Errorf("send-pack exited with error: %w", err)
176		}
177		return nil
178	}
179	
180	// readPushBatch collects the "push <src>:<dst>" lines that follow the
181	// initial firstLine (already consumed by the dispatcher), stopping at
182	// the blank line that terminates the batch.
183	func readPushBatch(firstLine string, stdin *bufio.Reader) ([]string, error) {
184		spec, ok := strings.CutPrefix(firstLine, "push ")
185		if !ok {
186			return nil, fmt.Errorf("expected 'push <src>:<dst>', got %q", firstLine)
187		}
188		refspecs := []string{spec}
189		for {
190			line, err := stdin.ReadString('\n')
191			if err != nil && err != io.EOF {
192				return nil, fmt.Errorf("reading push batch: %w", err)
193			}
194			line = strings.TrimRight(line, "\n\r")
195			if line == "" {
196				return refspecs, nil
197			}
198			spec, ok := strings.CutPrefix(line, "push ")
199			if !ok {
200				return nil, fmt.Errorf("expected 'push <src>:<dst>', got %q", line)
201			}
202			refspecs = append(refspecs, spec)
203			if err == io.EOF {
204				return refspecs, nil
205			}
206		}
207	}
208	
209	func killAndWaitSendPack(sp *exec.Cmd, reason string) {
210		if sp == nil || sp.Process == nil {
211			return
212		}
213		if err := sp.Process.Kill(); err != nil && !errors.Is(err, os.ErrProcessDone) {
214			debuglog.Printf("send-pack cleanup %s: kill: %v", reason, err)
215		}
216		if err := sp.Wait(); err != nil {
217			debuglog.Printf("send-pack cleanup %s: wait: %v", reason, err)
218		}
219	}
