266			payload := make([]byte, pktLen-pktline.LenSize)
267			if _, err := io.ReadFull(r, payload); err != nil {
268				return fmt.Errorf("reading send-pack packet payload: %w", err)
269			}
270			if _, err := dst.Write(payload); err != nil {
271				return fmt.Errorf("buffering send-pack packet payload: %w", err)
272			}
